const subscribedWebhookEndpoints = `-- name: SubscribedWebhookEndpoints :many
SELECT id, url, label, event_types, state, secret_sealed, secret_hint, previous_secret_sealed, previous_secret_until, challenge_hash, verified_at, failure_run, paused_reason, version, created_by, created_at, updated_at
FROM fyniq.webhook_endpoint WHERE state = 'active' AND $1::text = ANY (event_types) ORDER BY created_at, id
`

type SubscribedWebhookEndpointsRow struct {
	ID                   uuid.UUID
	Url                  string
	Label                string
	EventTypes           []string
	State                string
	SecretSealed         []byte
	SecretHint           string
	PreviousSecretSealed []byte
	PreviousSecretUntil  *time.Time
	ChallengeHash        *string
	VerifiedAt           *time.Time
	FailureRun           int32
	PausedReason         *string
	Version              int32
	CreatedBy            string
	CreatedAt            time.Time
	UpdatedAt            time.Time
}

func (q *Queries) SubscribedWebhookEndpoints(ctx context.Context, eventType string) ([]SubscribedWebhookEndpointsRow, error) {
	rows, err := q.db.Query(ctx, subscribedWebhookEndpoints, eventType)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SubscribedWebhookEndpointsRow
	for rows.Next() {
		var i SubscribedWebhookEndpointsRow
		if err := rows.Scan(
			&i.ID,
			&i.Url,
			&i.Label,
			&i.EventTypes,
			&i.State,
			&i.SecretSealed,
			&i.SecretHint,
			&i.PreviousSecretSealed,
			&i.PreviousSecretUntil,
			&i.ChallengeHash,
			&i.VerifiedAt,
			&i.FailureRun,
			&i.PausedReason,
			&i.Version,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
